places=[('vesuvio','Vesuvio / centrale','Vulcano sempre in eruzione con antenne e generatori che catturano energia dalla lava.','Proposta: climax sulla passerella di manutenzione; salvare un quartiere, non spegnere il vulcano.','the industrial slope of Mount Vesuvius overlooking Naples'),('canale','Il confine di lava','Napoli è separata fisicamente dal continente da un enorme canale di lava; origine ancora aperta.','Proposta: margine simbolico del libro. Non stabilire chi abbia creato il canale.','the immense active lava canal separating Naples from the mainland'),('ponticelli','Ponticelli / officina','Napoli e i mestieri robotici sono canonici; officina e deposito di Pacco compaiono nel trattamento video.','Proposta: officina come casa narrativa, luogo delle riparazioni e dei debiti.','a repair shed beneath the A3 viaduct in Ponticelli, Naples'),('porto','Porto / acqua nera','Il porto, la bonifica e la cella lavica sono presenti in Prima del boato.','Proposta: far pagare la perdita della cella con una scelta irreversibile, non con una semplice deviazione.','the industrial harbour of Naples, black water and corroded cranes'),('tetti','Cercola / antenne','Tetti, parabole e tornanti compaiono nel trattamento Prima del boato.','Proposta: scena di fiducia tra Pacco e Lucy; geografia condensata per il film.','the ash-covered rooftops and antenna masts of Cercola, Naples'),('rottami','Cimitero di ricambi','Montagne di rottami robotici ai margini delle zone abitate: motivo ambientale della lore.','Proposta: riparare qualcuno richiede rinunciare a un ricambio prezioso; niente rivelazione cosmologica automatica.','a robotic scrapyard on the industrial edge of Naples')]
cards=cast+ [dict(id=i,title=t,kind='Ambientazioni',lore=l,proposal=p,source=sources[2] if i in ['ponticelli','porto','tetti'] else sources[0],subject='a squat maintenance android in faded green steel carrying a brass toolbox',action='secures a loose service cable to a rusted railing',place=pl) for i,t,l,p,pl in places]
chapters=[('La ricevuta','Pacco vuole chiudere una normale consegna; una scossa rende fragile il tragitto.','Il bauletto si chiude, il percorso abituale salta.','Pacco; officina','Aprire sull’azione, non sulla spiegazione del mondo.'),('Chi ripara resta',"’O Meccanico tiene aperta l’officina mentre gli altri partono.",'Un pezzo prestato diventa un debito personale.','Pacco; officina','Far capire la comunità attraverso il lavoro.'),('Una voce sul filo','Lucy indica una deviazione, ma la rete non racconta tutta la verità.','Pacco accetta una guida che non vede.','Lucy; Cercola','Introdurre la seconda focalizzazione senza infodump.'),('Il bucato e la cenere','La corsa attraversa i cortili e disturba piccole abitudini ostinate.','Un aiuto minimo costa tempo prezioso.','Pacco; cortili','Umorismo di gesto e tenerezza concreta.'),('La strada sequestrata','Il Capitano impone il proprio ordine sul transito.','Consegna privata e priorità pubblica entrano in conflitto.','Pacco; svincoli','Il potere va mostrato attraverso un posto di blocco.'),('Il furto','La Vipera porta via la cella lavica.','Pacco sceglie di inseguire, perdendo la via sicura.','Pacco; Rione FIAT','Svolta di fine primo atto; base nel trattamento esistente.'),('Prezzi di quartiere','Gli aiuti passano attraverso favori e scambi.','Un patto compromette una futura via di fuga.','Lucy; mercato','Proposta nuova: costo sociale della corsa.'),('Il mare non aspetta','La cella cade nelle acque del porto.','Pacco deve affidarsi a chi conosce un ambiente diverso.','Pacco; porto','Usare Polpo e Delfino con funzione, non come catalogo.'),('Quello che ci raccontiamo','Durante una riparazione i ruoli ereditati diventano una questione personale.','Pacco difende la propria storia anche quando lo limita.','Pacco; officina','Il paradosso anti-IA emerge in dialoghi italiani quotidiani.'),('La destinazione cambia','La Lavandaia ha spostato l’impianto al fronte della colata.','Consegnare al luogo scritto non equivale più ad aiutare.','Lucy; ferrovia sul mare','Punto medio: cambiare criterio, non soltanto strada.'),('Trenta secondi in prestito','Il Mercante vende una finestra di passaggio.','La squadra perde una risorsa per guadagnare tempo.','Pacco; minimarket','Tenere chiara la catena causa-effetto.'),('La ragione del Capitano','L’energia contesa può tenere attive le pattuglie oppure la bonifica.','Il vantaggio di alcuni diventa danno per altri.','Pacco; salita','Non inventare un governo globale già stabilito.'),('La strada che resta','Don Circuito apre una via di servizio; qualcuno deve mantenerla percorribile.','Un alleato rinuncia a scappare per lasciare passare gli altri.','Lucy; Torre','Proposta di sacrificio operativo, non morte obbligatoria.'),('Prima del boato','L’eruzione cambia il paesaggio prima che arrivi il suono.','Il tragitto si rompe: servono le competenze accumulate.','Pacco; versante','Set piece basato su percezione, peso e conseguenze.'),('A chi arriva la luce','Pacco deve scegliere a cosa destinare la cella davanti alla Lavandaia.','La consegna diventa una responsabilità assunta.','Pacco; bonifica','Climax nuovo da approvare; vulcano ancora attivo.'),('La ricevuta aperta','La città riprende il lavoro, ma il debito dell’inizio non è sparito.','Pacco rientra diverso nello stesso luogo.','Pacco; officina','Finale autosufficiente; eventuale seguito non obbligatorio.')]
common='Naples architecture, Mount Vesuvius erupting with active orange lava and industrial generators, suspended ash, wet black volcanic stone, translucent aqua acrylic and mirror chrome against ruined masonry and massive retro military-industrial structures, vivid saturated full color, ultra high resolution'
for c in cards:
 c['prompts']={
 'FLUX 3':f"PROPOSED VISUAL STUDY, pending approval. SUBJECT: {c['subject']}. ACTION: {c['action']}. SETTING: {c['place']}. COMPOSITION: editorial cinematic study, three-quarter view, clearly readable silhouette and tangible props. LIGHT AND MATERIALS: warm lava backlight, cool aqua reflections, worn metal and wet surfaces. WORLD: {common}.",
 'MiniMax H3':f"integrated_multimodal_description: [Shot 1] {c['subject']} {c['action']}; the object settles with a heavy impact in {c['place']}. The camera tracks slowly sideways to reveal the physical consequence and the Neapolitan skyline. {common}. overall_soundscape: Mechanical joints, metal contact, wind carrying ash and continuous volcanic rumble. non_diegetic_music: N/A",
 'Pika':f"A single continuous cinematic shot: {c['subject']} {c['action']} in {c['place']}. Begin with the physical gesture, track sideways with the object, finish with it securely in place. Keep the same robot silhouette, accessory and material wear throughout. {common}."}
for c in cards:
 if c['kind']=='Ambientazioni':
  c['prompts']['FLUX 3']=f"PROPOSED ENVIRONMENT STUDY, pending approval. SETTING: {c['place']}. COMPOSITION: wide architectural environment photograph, unoccupied foreground, landscape and infrastructure are the main subject, layered spatial depth and readable scale. LIGHT AND MATERIALS: orange volcanic light, wet basalt, corroded steel, translucent aqua acrylic service housings and mirror chrome fittings among ruined masonry. WORLD: {common}."
