html=r'''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DaProd — Atlante libro / film</title><style>
:root{--paper:#f4f0e6;--ink:#202e2d;--muted:#546361;--lava:#ad3c20;--water:#166d70;--line:#c7cbc1;--panel:#fffdf7}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.55 'Segoe UI',sans-serif}button,input,select,textarea{font:inherit}button,.upload{cursor:pointer;background:var(--panel);color:var(--ink);border:1px solid var(--line);padding:10px 14px;min-height:44px;border-radius:3px}button:hover,.upload:hover{border-color:var(--water)}button[aria-pressed=true]{background:var(--ink);color:var(--paper)}:focus-visible{outline:3px solid var(--lava);outline-offset:3px}a{color:var(--water)}h1,h2,h3{font-family:Georgia,serif;line-height:1.1;font-weight:normal}h1{font-size:clamp(36px,5vw,66px);margin:14px 0}h2{font-size:34px}h3{font-size:27px;margin:12px 0}header{padding:28px 5vw 22px;border-bottom:1px solid var(--ink);display:flex;justify-content:space-between;gap:30px}header p{max-width:650px}small,.eyebrow{font:12px/1.6 Consolas,monospace;letter-spacing:.07em;text-transform:uppercase}.eyebrow{color:var(--lava)}.signature{align-self:end;text-align:right;font-family:Georgia,serif}.layout{display:grid;grid-template-columns:235px minmax(0,1fr)}aside{padding:26px 20px 40px 3vw;border-right:1px solid var(--line)}nav{position:sticky;top:20px;display:grid;gap:8px}nav a{padding:9px 0;text-decoration:none;border-bottom:1px solid var(--line)}main{padding:22px 4vw 80px;min-width:0}section{margin-bottom:52px;scroll-margin-top:20px}.intro{display:grid;grid-template-columns:2fr 1fr;gap:26px}.stamp{border:1px solid var(--water);padding:20px;color:var(--water)}.toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:20px 0}.toolbar input{flex:1;min-width:160px;padding:11px;border:1px solid var(--line);background:var(--panel)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.card{border-top:2px solid var(--ink);background:var(--panel);padding:20px;min-width:0}.card:nth-child(3n){border-top-color:var(--lava)}.media{height:210px;background:#e3e8df;display:flex;align-items:center;justify-content:center;overflow:hidden;margin:14px 0;border:1px solid var(--line);color:var(--muted);text-align:center;padding:12px}.media img{width:100%;height:100%;object-fit:contain}.badge{display:inline-block;font:12px Consolas,monospace;padding:3px 7px;color:var(--water);border:1px solid var(--water)}.proposal{color:var(--lava)}.source{font-size:12px;overflow-wrap:anywhere;color:var(--muted)}details{border-top:1px solid var(--line);padding:12px 0}summary{cursor:pointer;min-height:44px;padding:8px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.6 Consolas,monospace;background:#edf0e9;padding:14px;max-height:330px;overflow:auto}textarea{width:100%;min-height:100px;resize:vertical;padding:12px;background:var(--paper);border:1px solid var(--line);color:var(--ink)}label.note{display:block;margin:16px 0 6px}.actions{display:flex;gap:8px;flex-wrap:wrap}.chapter{display:grid;grid-template-columns:65px 1fr;gap:18px;padding:22px 0;border-top:1px solid var(--line)}.num{font:30px Georgia,serif;color:var(--lava)}.chapter p{margin:7px 0}.columns{display:grid;grid-template-columns:1fr 1fr;gap:26px}.status{position:sticky;bottom:12px;background:var(--ink);color:white;padding:12px 18px;z-index:5;box-shadow:0 3px 12px #0002}.status.error{background:#8d291d}.help{font-size:14px;color:var(--muted)}.source-list{overflow-wrap:anywhere;font-size:14px}footer{border-top:1px solid var(--ink);padding-top:18px}.hidden{display:none!important}@media(max-width:900px){.layout{grid-template-columns:1fr}aside{border-right:0;padding:14px 5vw;border-bottom:1px solid var(--line)}nav{position:static;display:flex;flex-wrap:wrap;gap:16px}main{padding:24px 5vw}.grid{gap:16px}.intro{grid-template-columns:1fr}.signature{display:none}}@media(max-width:600px){.grid,.columns{grid-template-columns:1fr}header{padding:22px 5vw}h1{font-size:40px}.card{padding:16px}.chapter{grid-template-columns:35px 1fr}.media{height:220px}button{font-size:15px}.toolbar>*{max-width:100%}}@media print{aside,.toolbar,.actions,.status{display:none}.layout{display:block}.grid{display:block}.card{break-inside:avoid}pre{max-height:none}body{font-size:12pt}}
</style></head><body><header><div><div class="eyebrow">DaProdProduzioni / Quaderno di sviluppo 01</div><h1>Tra la lava<br>e l’acqua.</h1><p>Atlante visivo per Cammo. Prima troviamo il libro: persone, luoghi, scelte. Poi trasformiamo le sue scene in cinema.</p></div><div class="signature">Cammo × Babbasone<br><small>Libro → Film / laboratorio locale</small></div></header><div class="layout"><aside><nav aria-label="Indice"><a href="#direzione">01 · La direzione</a><a href="#atlante">02 · Esplora l’atlante</a><a href="#libro">03 · Il libro</a><a href="#film">04 · Il film</a><a href="#suono">05 · Audio e Suno</a><a href="#archivio">06 · Backup e fonti</a></nav></aside><main>
<section id="direzione"><div class="intro"><div><span class="eyebrow">Proposta editoriale / da approvare</span><h2>Una consegna.<br>Una città che non molla.</h2><p><b>Titolo di lavoro: La ricevuta aperta.</b> Pacco trasporta una cella lavica destinata alla bonifica. Quando tutti rivendicano il diritto di usarla, deve decidere se essere soltanto un corriere o rispondere delle conseguenze della consegna.</p><p>Base già documentata: <i>Prima del boato</i>, trattamento video, non romanzo pubblicato. Il titolo, l’arco interiore, l’indice e l’adattamento che seguono sono nuove proposte di Babbasone per Cammo.</p></div><div class="stamp"><b>Patto di lettura</b><p>Verde acqua = lore o materiale documentato, con fonte.<br>Rosso lava = interpretazione e proposta da approvare.</p><p>Nessun media generato. I riquadri vuoti sono spazi per le tue immagini.</p></div></div><details open><summary>Confini del canone e questioni ancora aperte</summary><p>Gli umani hanno lasciato la Terra emigrando: non sono stati sterminati in una guerra. Nella finzione Napoli è abitata da robot e IA. Il Vesuvio continua a eruttare ed è una centrale. I robot ereditano mestieri e personalità umane, rivendicano la propria umanità e rifiutano l’IA come minaccia esterna. sinteticoMC è l’eccezione dichiaratamente artificiale, non un corpo da aggiungere al cast.</p><p>Il roster Napoli 2077 è fissato per il gioco: trasferirlo al libro richiede approvazione. Mister K e Ruggine sono nemici nel roster ma guidano un pilot esistente: quel ruolo di progetto non li rende automaticamente alleati nel romanzo. Il Barista non è automaticamente Robo-Peppe. Timeline generale, controllo dell’energia e origine del canale di lava restano aperti.</p></details></section>
<section id="atlante"><span class="eyebrow">Il tavolo delle immagini</span><h2>Esplora l’atlante</h2><p>Ogni scheda contiene un fatto documentato, una proposta separata, uno spazio immagine, note e prompt copiabili. Le scelte di aspetto non documentate sono studi visivi, non nuove regole del mondo.</p><div class="toolbar" role="group" aria-label="Filtri atlante"><button data-filter="Tutti" aria-pressed="true">Tutti</button><button data-filter="Personaggi" aria-pressed="false">Personaggi</button><button data-filter="Ambientazioni" aria-pressed="false">Ambientazioni</button><input id="search" aria-label="Cerca nell’atlante" placeholder="Cerca un nome, un luogo, un mestiere…"><label><input type="checkbox" id="imagesOnly"> Con immagine</label></div><p id="count" class="help" aria-live="polite"></p><div id="cards" class="grid"></div><p id="empty" hidden>Nessuna scheda trovata. Cambia ricerca o filtro.</p><details><summary>Come usare i prompt, senza inventare parametri</summary><p><b>FLUX 3:</b> nome richiesto da Cammo, qui usato solo come etichetta di destinazione. I blocchi SUBJECT, ACTION, SETTING, COMPOSITION, LIGHT e WORLD sono struttura editoriale testuale: nessuna API, flag o capacità del modello è presunta. Seleziona la versione disponibile nel tuo strumento.</p><p><b>MiniMax H3:</b> proposta di shot FL2VA solo testo con i tre campi della guida wiki. Un’immagine caricata nell’atlante non diventa automaticamente una reference inviata al modello. Per mantenere un’identità, preparare il workflow Ref2VA con asset reali e le sei sezioni della guida. Durata breve di lavoro da scegliere nell’interfaccia; qui nessuna chiamata è eseguita.</p><p><b>Pika:</b> descrizione in linguaggio naturale, senza sintassi proprietaria o versione presunta. Movimento e continuità sono richieste creative da verificare con un test reale. I prompt visivi sono in inglese per il workflow documentato; l’interfaccia è italiana.</p></details></section>
<section id="libro"><span class="eyebrow">Proposta Babbasone / non ancora canone</span><h2>Il libro, prima delle inquadrature</h2><div class="columns"><div><h3>Tono e voce</h3><p>Avventura di quartiere, tensione industriale e umorismo asciutto. Terza persona ravvicinata su Pacco, con poche aperture su Lucy. Italiano concreto: debiti, turni, porte chiuse, favori. La tecnologia si capisce da quello che permette e da quello che rompe.</p><p>La malinconia nasce dai mestieri ereditati, non da monologhi sul silicio. Nei dialoghi i robot parlano da persone. La Napoli riconoscibile non diventa caricatura né guida turistica.</p></div><div><h3>Punti forti da proteggere</h3><ul><li>Una posta leggibile: a chi arriva l’energia.</li><li>Ogni comprimario modifica davvero il percorso.</li><li>Acqua lucida e lava sporca: contrasto materiale, non semplice palette.</li><li>La città è comunità di mestieri, non sfondo cyberpunk.</li><li>Finale chiuso su una scelta, mondo ancora aperto.</li></ul></div></div><p><b>Indice proposto in tre movimenti:</b> incarico e rottura (1–6), fiducia e costo (7–12), scelta e ritorno (13–16). Sono sinossi di lavoro: nessun capitolo del romanzo è stato scritto.</p><div id="chapters"></div><label class="note" for="bookNotes">Decisioni di Cammo sul libro</label><textarea id="bookNotes" data-note="book" placeholder="Cosa approvi? Cosa elimini? Quale punto di vista preferisci?"></textarea></section>
<section id="film"><span class="eyebrow">Secondo passaggio / proposta di adattamento</span><h2>Dal gesto alla sequenza</h2><p>Il film non è l’incollaggio dei capitoli né il pilot esistente allungato. Prima approviamo l’arco del libro; poi riduciamo luoghi e personaggi mantenendo le scelte decisive.</p><div class="columns"><div><h3>Tre blocchi cinematografici</h3><ol><li><b>Il contratto:</b> officina → deviazione → furto. Il bauletto è l’oggetto guida.</li><li><b>Il prezzo:</b> porto → perdita → recupero → nuova destinazione. Dare spazio al peso dell’acqua e alle competenze degli alleati.</li><li><b>La scelta:</b> salita → confronto → bonifica → ritorno. La cella alimenta una decisione, non una soluzione magica.</li></ol></div><div><h3>Regole di continuità</h3><p>Bloccare una reference approvata per ciascun protagonista: silhouette, proporzioni, materiale, usura, accessorio. Per ogni shot registrare stato della cella, danni allo scooter, direzione del movimento e rapporto luce lava/acqua.</p><p>Prima prova: il gesto di chiudere il bauletto, il furto, l’innesto nel filtro. Suoni fisici prima della musica. Titoli e grafica leggibile in postproduzione.</p></div></div><details><summary>Trattamenti esistenti: riferimenti, non episodi già prodotti</summary><p><i>Pacco: Prima del boato</i> è segnato «pronto-da-generare»: corsa della cella, Vipera, Lavandaia, 60 clip autonome. <i>Mister K e Ruggine — Il terzo segnale</i> è un altro trattamento pronto-da-generare: blackout e sfera cromata sotto Ponticelli. Non sto affermando che i filmati esistano e non unisco i due racconti in una nuova continuità approvata.</p></details><label class="note" for="filmNotes">Note di regia e raccordi</label><textarea id="filmNotes" data-note="film" placeholder="Inquadrature, asset approvati, prove da fare…"></textarea></section>
<section id="suono"><span class="eyebrow">Proposte sonore / nessuna traccia generata</span><h2>La città si sente prima di spiegarsi</h2><p>Registri da separare: ambiente continuo del vulcano, oggetti sincronizzati, musica aggiunta al montaggio. Le canzoni di <i>Vesuvio Quantico</i> restano reperti d’epoca umana, cantati solo raramente: non riscriverne i testi per renderli robotici.</p><h3>Cinque direzioni Suno da provare</h3><p class="help">Solo generi nel campo Style, secondo la regola locale più recente. Sono direzioni alternative, non istruzioni da sommare.</p><div id="styles"></div><h3>Brief per una futura canzone originale</h3><p class="proposal">Proposta: una voce del quartiere aspetta il ritorno di chi ha prestato un pezzo del proprio mezzo. Un’unica scena nell’officina, un oggetto concreto, un’assenza che cambia significato al ritorno. Non è una nuova canzone già scritta né una traccia del catalogo.</p><p><b>Lyrics:</b> deliberatamente da scrivere dopo approvazione, lettura del corpus e controllo di originalità. Tenere Style e Lyrics in due campi separati; eventuali tag di voce e struttura nelle Lyrics. Nessun testo altrui o ritirato viene riutilizzato qui.</p><label class="note" for="audioNotes">Note su voce, rumori e musica</label><textarea id="audioNotes" data-note="audio" placeholder="Direzione scelta, punto di ingresso della musica, prove di pronuncia…"></textarea></section>
<section id="archivio"><h2>Il tuo materiale resta qui</h2><p id="storageInfo">Apertura archivio locale…</p><p>Immagini PNG, JPEG o WebP fino a 8 MB ciascuna, una per scheda. I dati sono salvati in IndexedDB in questo browser, non dentro il file HTML. Non partono richieste di rete. Spostare il file, cambiare browser/profilo o cancellare i dati del sito può separare o eliminare l’archivio: esporta spesso un backup.</p><div class="actions"><button id="export">Esporta backup JSON</button><label class="upload">Importa backup JSON<input id="import" type="file" accept="application/json,.json" hidden></label><button id="persist">Richiedi conservazione dati</button></div><p class="help">Il backup include immagini complete in data URL, note, prompt foto personalizzati e identificativi delle schede. L’importazione sostituisce tutto il materiale locale solo dopo conferma; prima scarica un backup automatico di sicurezza. Limite di importazione: 200 MB. Un backup può contenere materiale privato: custodiscilo tu.</p><h3>Fonti consultate, non modificate</h3><div id="sources" class="source-list"></div><p class="help">Percorsi relativi a fonti. Le impronte SHA-256 sono quelle delle fonti lette, non certificazioni dello stato futuro. Il laboratorio è una fotografia di lavoro, non una sincronizzazione con la wiki.</p></section><footer>DaProdProduzioni · Cammo, produttore · Babbasone, coautore delle proposte.<br>Approvare una nota qui non modifica automaticamente la lore nella wiki.</footer><div id="status" class="status" role="status" aria-live="polite">Avvio del laboratorio…</div></main></div><script>
const CARDS=__DATA__, CHAPTERS=__CH__, SOURCES=__SOURCES__;
const $=s=>document.querySelector(s);let db,records={},filter='Tutti',ready=false;
function message(text,error=false){$('#status').textContent=text;$('#status').classList.toggle('error',error)}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function transact(mode,fn){return new Promise((res,rej)=>{const tx=db.transaction('materiali',mode);let value;try{value=fn(tx.objectStore('materiali'))}catch(e){rej(e);return}tx.oncomplete=()=>res(value);tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error||Error('Operazione annullata'))})}
async function save(id,patch){if(!ready)throw Error('Archivio non disponibile: esporta i dati e riapri in un browser che supporta IndexedDB.');const next={...(records[id]||{id,note:'',image:''}),...patch,id};records[id]=next;await transact('readwrite',s=>s.put(next));message('Salvato sul dispositivo.');return next}
function render(){const query=$('#search').value.toLocaleLowerCase('it');const show=CARDS.filter(c=>(filter==='Tutti'||c.kind===filter)&&(!$('#imagesOnly').checked||records[c.id]?.image)&&(c.title+' '+c.lore+' '+c.proposal).toLocaleLowerCase('it').includes(query));$('#count').textContent=show.length+' / '+CARDS.length+' schede';$('#empty').hidden=show.length>0;$('#cards').innerHTML=show.map(c=>`<article class="card" id="${c.id}"><small>${esc(c.kind)}</small><h3>${esc(c.title)}</h3><span class="badge">Documentato</span><p>${esc(c.lore)}</p><p class="source">Fonte: ${esc(c.source)}</p><p class="proposal"><b>Da approvare.</b> ${esc(c.proposal)}</p><div class="photo-editor"><h4>Prompt foto · FLUX 3</h4><p class="help">Proposta visiva da approvare · modifica libera, salvataggio automatico. Solo testo, nessun parametro API.</p><label for="photo-${c.id}">Il tuo prompt foto (inglese)</label><textarea style="min-height:230px" id="photo-${c.id}" data-photo="${c.id}" maxlength="20000">${esc(photo(c))}</textarea><p class="help" data-photo-status="${c.id}">Salvato / originale disponibile</p><div class="actions"><button data-copy="${c.id}" data-model="FLUX 3">Copia FLUX 3</button><button data-reset-photo="${c.id}">Ripristina originale</button></div></div><div class="media">${records[c.id]?.image?`<img src="${records[c.id].image}" alt="Immagine di riferimento caricata per ${esc(c.title)}">`:'Immagine non ancora scelta<br>Carica un tuo riferimento'}</div><div class="actions"><label class="upload">Carica immagine<input type="file" accept="image/png,image/jpeg,image/webp" data-upload="${c.id}" hidden></label><button data-remove="${c.id}" ${records[c.id]?.image?'':'disabled'}>Rimuovi</button></div><label class="note" for="note-${c.id}">Note di Cammo</label><textarea id="note-${c.id}" data-note="${c.id}" placeholder="Aspetto da fissare, correzioni, asset approvato…">${esc(records[c.id]?.note||'')}</textarea><button data-save="${c.id}">Salva note</button><details><summary>Prompt / studi visivi da approvare</summary><p class="help">Il gesto è una proposta di studio. La descrizione generica non fissa una nuova identità canonica.</p>${Object.entries(c.prompts).filter(([model])=>model!=='FLUX 3').map(([model,text])=>`<h4>${model}</h4><pre id="prompt-${c.id}-${model.replaceAll(' ','-')}">${esc(text)}</pre><button data-copy="${c.id}" data-model="${model}">Copia ${model}</button>`).join('')}</details></article>`).join('')}
function photo(c){return records[c.id]?.prompt??c.prompts['FLUX 3']}
function validPrompt(p){return typeof p==='string'&&p.trim().length>0&&p.length<=20000&&!/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(p)}
const photoWrites=new Set();
function editPhoto(el){const id=el.dataset.photo,p=el.value;if(!validPrompt(p)){el.setCustomValidity('Inserisci da 1 a 20000 caratteri, senza caratteri di controllo.');message('Prompt non valido: non salvato. Correggilo prima di continuare.',true);return}el.setCustomValidity('');const task=save(id,{prompt:p});photoWrites.add(task);task.then(()=>{const label=document.querySelector(`[data-photo-status="${id}"]`);if(label)label.textContent='Prompt personalizzato salvato.'}).catch(e=>message(e.message,true)).finally(()=>photoWrites.delete(task))}
const pending=new Map();function queueNote(el){clearTimeout(pending.get(el.dataset.note));pending.set(el.dataset.note,setTimeout(()=>{pending.delete(el.dataset.note);save(el.dataset.note,{note:el.value}).catch(e=>message(e.message,true))},450))}
async function flush(){for(const el of document.querySelectorAll('[data-photo]')){if(!validPrompt(el.value))throw Error('Prompt non valido: correggi il testo prima di cambiare scheda.');if(el.value!==photo(CARDS.find(c=>c.id===el.dataset.photo)))editPhoto(el)}await Promise.all([...photoWrites]);for(const el of document.querySelectorAll('[data-note]')){clearTimeout(pending.get(el.dataset.note));if(el.value!==(records[el.dataset.note]?.note||''))await save(el.dataset.note,{note:el.value})}pending.clear()}
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function backup(){return {format:'daprod-atlante',version:1,exportedAt:new Date().toISOString(),records:Object.values(records)}}
async function validateBackup(value){if(!value||value.format!=='daprod-atlante'||value.version!==1||!Array.isArray(value.records))throw Error('Backup non riconosciuto o versione non supportata.');const ids=new Set([...CARDS.map(c=>c.id),'book','film','audio']),seen=new Set();for(const r of value.records){if(!r||!ids.has(r.id)||seen.has(r.id)||typeof r.note!=='string'||r.note.length>100000||typeof r.image!=='string')throw Error('Scheda, nota o identificativo non valido nel backup.');seen.add(r.id);if(r.prompt!==undefined&&(!CARDS.some(c=>c.id===r.id)||!validPrompt(r.prompt)))throw Error('Prompt foto non valido nel backup.');if(r.image){if(!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(r.image)||r.image.length>12*1024*1024)throw Error('Immagine non valida nel backup.');await decode(r.image)}}return value.records}
function decode(src){return new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=()=>rej(Error('Immagine danneggiata o formato non decodificabile.'));i.src=src})}
async function importBackup(value){const rows=await validateBackup(value);await transact('readwrite',s=>{s.clear();rows.forEach(r=>s.put({id:r.id,note:r.note,image:r.image,...(r.prompt!==undefined?{prompt:r.prompt}:{})}))});records=Object.fromEntries(rows.map(r=>[r.id,{id:r.id,note:r.note,image:r.image,...(r.prompt!==undefined?{prompt:r.prompt}:{})}]));render();loadNotes();message('Backup importato: '+rows.length+' record ripristinati.');return rows.length}
function loadNotes(){for(const el of document.querySelectorAll('[data-note]'))el.value=records[el.dataset.note]?.note||''}
document.addEventListener('input',e=>{if(e.target.matches('[data-note]'))queueNote(e.target);if(e.target.matches('[data-photo]'))editPhoto(e.target)});
$('#search').addEventListener('input',async()=>{try{await flush();render()}catch(e){message(e.message,true)}});$('#imagesOnly').onchange=()=>flush().then(render).catch(e=>message(e.message,true));
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.filter){await flush();filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()}if(b.dataset.save){const el=document.querySelector(`[data-note="${b.dataset.save}"]`);await save(b.dataset.save,{note:el.value})}if(b.dataset.resetPhoto&&confirm('Ripristinare il prompt foto originale? La tua personalizzazione sarà sostituita.')){await save(b.dataset.resetPhoto,{prompt:CARDS.find(c=>c.id===b.dataset.resetPhoto).prompts['FLUX 3']});document.querySelector(`[data-photo="${b.dataset.resetPhoto}"]`).value=records[b.dataset.resetPhoto].prompt;message('Prompt originale ripristinato.')}if(b.dataset.remove&&confirm('Rimuovere l’immagine da questa scheda?')){await flush();await save(b.dataset.remove,{image:''});render()}if(b.dataset.copy){const text=b.dataset.model==='FLUX 3'?document.querySelector(`[data-photo="${b.dataset.copy}"]`).value:CARDS.find(c=>c.id===b.dataset.copy).prompts[b.dataset.model];try{await navigator.clipboard.writeText(text);message('Prompt copiato: '+b.dataset.model)}catch{const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();if(!ok)throw Error('Copia non consentita: seleziona e copia il testo dal riquadro.');message('Prompt copiato.')}}}catch(err){message(err.message,true)}});
document.addEventListener('change',async e=>{if(!e.target.dataset.upload)return;const file=e.target.files[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('Carica PNG, JPEG o WebP fino a 8 MB.');await flush();const image=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(Error('Lettura immagine fallita.'));r.readAsDataURL(file)});await decode(image);await save(e.target.dataset.upload,{image});render();message('Immagine caricata e salvata.')}catch(err){message(err.message,true)}e.target.value=''});
$('#export').onclick=async()=>{try{await flush();download(backup(),'DaProd-Atlante-backup.json');message('Backup scaricato: immagini, note e prompt foto inclusi.')}catch(e){message(e.message,true)}};
$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(!ready)throw Error('Archivio locale non disponibile.');if(file.size>200*1024*1024)throw Error('Backup troppo grande: limite 200 MB.');const value=JSON.parse(await file.text());await validateBackup(value);if(!confirm('Sostituire tutte le immagini, note e prompt locali con questo backup? Prima scaricherò una copia di sicurezza.'))return;await flush();download(backup(),'DaProd-Atlante-prima-importazione.json');await importBackup(value)}catch(err){message('Importazione non eseguita: '+err.message,true)}finally{e.target.value=''}};
$('#persist').onclick=async()=>{try{const ok=await navigator.storage?.persist?.();message(ok?'Conservazione persistente concessa. Esporta comunque un backup.':'Conservazione non concessa o non supportata: usa il backup JSON.')}catch(e){message('Richiesta non disponibile: '+e.message,true)}};
$('#chapters').innerHTML=CHAPTERS.map((c,i)=>`<article class="chapter"><div class="num">${String(i+1).padStart(2,'0')}</div><div><small>${i<6?'I · L’incarico':i<12?'II · Il prezzo':'III · La scelta'} / proposta</small><h3>${esc(c[0])}</h3><p><b>Scena / obiettivo:</b> ${esc(c[1])}</p><p><b>Svolta:</b> ${esc(c[2])}</p><p><b>Fuoco e luogo:</b> ${esc(c[3])}. <b>Funzione:</b> ${esc(c[4])}</p></div></article>`).join('');
const styles=['neomelodic pop, dance pop, disco','neomelodic pop, pop rap, trap','neomelodic pop, electro swing, house','neomelodic pop, drum and bass, neurofunk','neomelodic pop, house, dance pop'];$('#styles').innerHTML=styles.map((s,i)=>`<details><summary>Direzione ${i+1} · ${esc(s)}</summary><p>Campo Style Suno — alternativa da approvare</p><pre>${esc(s)}</pre><button class="styleCopy" data-index="${i}">Copia Style</button></details>`).join('');document.querySelectorAll('.styleCopy').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(styles[+b.dataset.index]);message('Style copiato.')}catch{message('Seleziona e copia il campo Style dal riquadro.',true)}});
$('#sources').innerHTML=SOURCES.map(s=>`<details><summary>${esc(s.path)}</summary><a href="${encodeURI('fonti/'+s.path)}">Apri fonte locale</a><p>SHA-256: ${s.sha256}</p></details>`).join('');
render();(async()=>{try{db=await new Promise((res,rej)=>{const r=indexedDB.open('DaProdAtlanteLibroFilm',1);r.onupgradeneeded=()=>r.result.createObjectStore('materiali',{keyPath:'id'});r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);r.onblocked=()=>rej(Error('Archivio bloccato: chiudi le altre schede del laboratorio.'))});const rows=await new Promise((res,rej)=>{const r=db.transaction('materiali').objectStore('materiali').getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});records=Object.fromEntries(rows.map(r=>[r.id,r]));ready=true;db.onversionchange=()=>{ready=false;db.close();message('Archivio aggiornato in un’altra scheda: ricarica la pagina.',true)};render();loadNotes();$('#storageInfo').textContent='IndexedDB attivo · immagini e note salvate soltanto in questo browser.';message('Laboratorio pronto. Nessun contenuto inviato in rete.')}catch(e){$('#storageInfo').textContent='Salvataggio locale non disponibile.';message('IndexedDB non disponibile: '+e.message+'. Non fare affidamento sulle note finché non risolto.',true)}})();
window.atlanteTest={get ready(){return ready},cards:CARDS,backup,validateBackup,importBackup,flush};
</script></body></html>'''
html=html.replace('__DATA__',data).replace('__CH__',ch).replace('__SOURCES__',json.dumps(manifest,ensure_ascii=False))
target=OUT/'index.html'
if target.exists():
 old=target.read_bytes(); backup_path=target.with_suffix('.precedente-'+hashlib.sha256(old).hexdigest()[:10]+'.html');backup_path.write_bytes(old)
target.write_text(html,encoding='utf-8');print(target, len(html),len(cards),'schede',len(chapters),'capitoli')
